-- Esclusioni (nessuna sovrapposizione di istruttore/sala)
alter table public.course_sessions add constraint course_sessions_instructor_no_overlap EXCLUDE USING gist (instructor_staff_user_id WITH =, tstzrange(starts_at, ends_at, '[)'::text) WITH &&) WHERE (((status <> 'cancelled'::text) AND (instructor_staff_user_id IS NOT NULL)));
alter table public.course_sessions add constraint course_sessions_room_no_overlap EXCLUDE USING gist (room_id WITH =, tstzrange(starts_at, ends_at, '[)'::text) WITH &&) WHERE ((status <> 'cancelled'::text));

-- Check
alter table public.access_credentials add constraint access_credentials_type_check CHECK ((type = ANY (ARRAY['card'::text, 'nfc'::text, 'qr'::text])));
alter table public.accounting_entries add constraint accounting_entries_direction_check CHECK ((direction = ANY (ARRAY['income'::text, 'expense'::text])));
alter table public.bodygate_atomic_operations add constraint bodygate_atomic_operations_idempotency_key_check CHECK (((char_length(idempotency_key) >= 16) AND (char_length(idempotency_key) <= 180)));
alter table public.bodygate_atomic_operations add constraint bodygate_atomic_operations_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text));
alter table public.bodygate_atomic_operations add constraint bodygate_atomic_operations_status_check CHECK ((status = ANY (ARRAY['processing'::text, 'completed'::text])));
alter table public.bodygate_atomic_operations add constraint bodygate_atomic_operations_type_check CHECK ((operation_type = ANY (ARRAY['membership_fee_renewal'::text, 'platinum_onboarding'::text, 'course_type_create'::text, 'course_room_create'::text, 'course_schedule_create'::text, 'course_sessions_generate'::text, 'course_booking_create'::text, 'course_booking_cancel'::text, 'course_booking_check_in'::text, 'course_session_complete'::text, 'course_session_cancel'::text, 'course_enrollment_create'::text, 'course_enrollment_cancel'::text, 'course_enrollment_sync'::text, 'course_booking_pay'::text, 'course_enrollment_payment_renew'::text])));
alter table public.course_bookings add constraint course_bookings_source_check CHECK ((booking_source = ANY (ARRAY['reception'::text, 'admin'::text, 'mobile_pass'::text, 'system'::text, 'import'::text])));
alter table public.course_bookings add constraint course_bookings_status_check CHECK ((status = ANY (ARRAY['confirmed'::text, 'waitlisted'::text, 'cancelled'::text, 'attended'::text, 'no_show'::text])));
alter table public.course_bookings add constraint course_bookings_waitlist_check CHECK ((((status = 'waitlisted'::text) AND (waitlist_position IS NOT NULL) AND (waitlist_position > 0)) OR ((status <> 'waitlisted'::text) AND (waitlist_position IS NULL))));
alter table public.course_enrollments add constraint course_enrollments_billing_cycle_check CHECK ((billing_cycle = ANY (ARRAY['monthly'::text, 'quarterly'::text, 'annual'::text])));
alter table public.course_enrollments add constraint course_enrollments_fixed_price_required CHECK (((pricing_mode <> 'fixed'::text) OR (fixed_price IS NOT NULL)));
alter table public.course_enrollments add constraint course_enrollments_pricing_mode_check CHECK ((pricing_mode = ANY (ARRAY['fixed'::text, 'per_session'::text])));
alter table public.course_enrollments add constraint course_enrollments_status_check CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text, 'cancelled'::text])));
alter table public.course_rooms add constraint course_rooms_capacity_check CHECK ((capacity > 0));
alter table public.course_schedules add constraint course_schedules_capacity_check CHECK ((capacity > 0));
alter table public.course_schedules add constraint course_schedules_dates_check CHECK (((valid_until IS NULL) OR (valid_until >= valid_from)));
alter table public.course_schedules add constraint course_schedules_duration_check CHECK (((duration_minutes > 0) AND (duration_minutes <= 1440)));
alter table public.course_schedules add constraint course_schedules_horizon_check CHECK (((generation_horizon_days >= 1) AND (generation_horizon_days <= 366)));
alter table public.course_schedules add constraint course_schedules_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'paused'::text, 'archived'::text])));
alter table public.course_schedules add constraint course_schedules_weekday_check CHECK (((weekday >= 1) AND (weekday <= 7)));
alter table public.course_sessions add constraint course_sessions_booking_window_check CHECK (((booking_opens_at IS NULL) OR (booking_closes_at IS NULL) OR (booking_opens_at <= booking_closes_at)));
alter table public.course_sessions add constraint course_sessions_capacity_check CHECK ((capacity > 0));
alter table public.course_sessions add constraint course_sessions_status_check CHECK ((status = ANY (ARRAY['scheduled'::text, 'open'::text, 'closed'::text, 'completed'::text, 'cancelled'::text])));
alter table public.course_sessions add constraint course_sessions_time_check CHECK ((starts_at < ends_at));
alter table public.course_types add constraint course_types_capacity_check CHECK ((default_capacity > 0));
alter table public.course_types add constraint course_types_cutoff_check CHECK ((cancellation_cutoff_minutes >= 0));
alter table public.course_types add constraint course_types_duration_check CHECK (((default_duration_minutes > 0) AND (default_duration_minutes <= 1440)));
alter table public.course_types add constraint course_types_slug_check CHECK ((slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'::text));
alter table public.staff_access_credentials add constraint staff_access_credentials_type_check CHECK ((type = ANY (ARRAY['card'::text, 'nfc'::text, 'qr'::text])));
alter table public.subscription_renewal_operations add constraint subscription_renewal_operations_idempotency_key_check CHECK (((char_length(idempotency_key) >= 16) AND (char_length(idempotency_key) <= 180)));
alter table public.subscription_renewal_operations add constraint subscription_renewal_operations_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text));
alter table public.subscription_renewal_operations add constraint subscription_renewal_operations_status_check CHECK ((status = ANY (ARRAY['processing'::text, 'completed'::text])));

